import cadquery as cq
import math

# Generated by Studio CAD


# Plate and four holes
sketch_1 = cq.Workplane(cq.Plane.named("XY"))
loop_1 = sketch_1.moveTo(-40.0, -20.0)
loop_1 = loop_1.lineTo(40.0, -20.0)
loop_1 = loop_1.lineTo(40.0, 20.0)
loop_1 = loop_1.lineTo(-40.0, 20.0)
loop_1 = loop_1.lineTo(-40.0, -20.0)
loop_1 = loop_1.close()
loop_2 = sketch_1.moveTo(-32.0, -12.0).circle(4.0)
loop_3 = sketch_1.moveTo(32.0, -12.0).circle(4.0)
loop_4 = sketch_1.moveTo(-32.0, 12.0).circle(4.0)
loop_5 = sketch_1.moveTo(32.0, 12.0).circle(4.0)
sketch_1 = sketch_1.add(loop_1).add(loop_2).add(loop_3).add(loop_4).add(loop_5)

# Plate extrusion
body_1 = sketch_1.extrude(8.0, both=False, combine=False)

# Combine bodies and export
result = body_1
cq.exporters.export(result, "model.step")
cq.exporters.export(result, "model.stl")
